"use client";
import { useEffect, useRef, useState } from "react";
import Form from "next/form";
import Link from "next/link";
import { Plus, Search } from "lucide-react";
import { EmptyState } from "@/components/common";
import { Pagination } from "@/components/pagination";
import { TemplateListItem, type SavedTemplate } from "./TemplateListItem";
import styles from "./templates.module.css";

export function TemplatesPremiumView({
  templates,
  total,
  q,
  page,
  pageSize,
  query,
  searchEnabled,
}: {
  templates: SavedTemplate[];
  total: number;
  q: string;
  page: number;
  pageSize: number;
  query: Record<string, string>;
  searchEnabled: boolean;
}) {
  const [openId, setOpenId] = useState<string | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const clearTimer = () => {
    if (timer.current) clearTimeout(timer.current);
    timer.current = null;
  };
  useEffect(() => clearTimer, []);
  const newHref = `/templates?${new URLSearchParams({ ...query, new: "1" })}`;
  return (
    <div className={`${styles.scope} text-foreground min-w-0`}>
      <header
        className={`workspace-screen-heading flex justify-between items-end gap-5 flex-wrap [margin:16px_0_28px]`}
      >
        <div>
          <p
            className={`m-0 mb-2.5 text-[var(--tpl-token)] workspace-mono:text-[var(--coral)] [font:500_11.5px_var(--font-jetbrains),_monospace] tracking-[0.12em] uppercase`}
          >
            Your workspace
          </p>
          <h1 className="mt-2 text-[clamp(30px,4.6vw,46px)] leading-[1.08] tracking-[-0.04em] font-extrabold">
            Templates
          </h1>
          <p className="text-[var(--tpl-muted)] mt-2">
            Find the right message for your next introduction.
          </p>
        </div>
        <Link
          className={`${styles.primary} button-interaction primary-action [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] shadow-none inline-flex items-center justify-center gap-2 py-[11px] px-5.5 min-h-11 rounded-full font-bold text-[14px] [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] shadow-none no-underline shrink-0`}
          href={newHref}
        >
          <Plus size={18} aria-hidden="true" />
          New template
        </Link>
      </header>
      {searchEnabled && (
        <Form
          action="/templates"
          className={`field-focus-wrapper ${styles.search} flex items-center gap-3 py-0 px-4.5 rounded-[16px] [border:1px_solid_var(--tpl-line)] [background:var(--tpl-card)] min-h-13 text-[var(--tpl-muted)] [@media(max-width:_480px)]:gap-2 [@media(max-width:_480px)]:py-0 [@media(max-width:_480px)]:px-3`}
          onSubmit={clearTimer}
        >
          <Search size={18} aria-hidden="true" />
          <input
            key={q}
            className="min-w-0 flex-1 bg-none border-0 h-12.5 text-foreground [font:inherit] placeholder:text-[var(--tpl-muted)]"
            type="search"
            name="q"
            aria-label="Search templates"
            defaultValue={q}
            maxLength={160}
            placeholder="Search by name or subject…"
            autoComplete="off"
            onChange={(event) => {
              clearTimer();
              const form = event.currentTarget.form;
              // IME composition finishes before scheduling a search.
              if (
                event.nativeEvent instanceof InputEvent &&
                event.nativeEvent.isComposing
              )
                return;
              timer.current = setTimeout(() => form?.requestSubmit(), 250);
            }}
            onCompositionEnd={(event) => {
              clearTimer();
              const form = event.currentTarget.form;
              timer.current = setTimeout(() => form?.requestSubmit(), 250);
            }}
          />
          <button type="submit" className="min-h-11 text-[13px] cursor-pointer">
            Search
          </button>
        </Form>
      )}
      <div
        className={`flex items-center flex-wrap gap-4 text-[var(--tpl-muted)] text-[13.5px] [margin:30px_0_14px]`}
      >
        <h2 className="mr-auto text-[18px] text-foreground font-bold tracking-[-0.02em]">
          Saved templates
        </h2>
        <p role="status">
          {total}{" "}
          {q
            ? total === 1
              ? "result"
              : "results"
            : total === 1
              ? "template"
              : "templates"}
        </p>
        {q && (
          <Link
            className="text-link min-h-11 inline-flex items-center"
            href="/templates"
          >
            Clear search
          </Link>
        )}
      </div>
      {!templates.length ? (
        <EmptyState
          title={
            page > 1
              ? "No templates on this page"
              : q
                ? "No matching templates"
                : "Your template collection starts here"
          }
          description={
            page > 1
              ? "Return to the first page to see your saved templates."
              : q
                ? `No templates match “${q}”. Try a different name or subject.`
                : "Create reusable messages for introductions, follow-ups, and more."
          }
          href={
            page > 1
              ? `/templates${q ? `?${new URLSearchParams({ q })}` : ""}`
              : q
                ? "/templates"
                : newHref
          }
          link={
            page > 1
              ? "Back to templates"
              : q
                ? "Clear search"
                : "Create your first template"
          }
        />
      ) : (
        <ul
          className="grid gap-3 p-0 list-none"
          aria-label="Saved templates"
          onKeyDown=[REDACTED_SECRET]
            if (
              event.key === "Escape" &&
              openId &&
              !(event.target as Element).closest("dialog")
            ) {
              event.preventDefault();
              const row = (event.target as Element).closest("li");
              row
                ?.querySelector<HTMLButtonElement>("button[aria-expanded]")
                ?.focus();
              setOpenId(null);
            }
          }}
        >
          {templates.map((template) => (
            <TemplateListItem
              key={template.id}
              template={template}
              open={openId === template.id}
              onToggle={() =>
                setOpenId(openId === template.id ? null : template.id)
              }
              editHref={`/templates?${new URLSearchParams({ ...query, edit: template.id })}`}
            />
          ))}
        </ul>
      )}
      {total > 0 && (
        <div className={`${styles.pagination} mt-5`}>
          <Pagination
            path="/templates"
            page={page}
            total={total}
            pageSize={pageSize}
            query={q ? { q } : {}}
          />
        </div>
      )}
    </div>
  );
}
